"""Build static review from actual RunPod artifacts. No raster processing."""
import json
from pathlib import Path
root=Path(__file__).resolve().parents[3]
out=root/'runs/hemp-point-loop-v1';out.mkdir(parents=True,exist_ok=True)
reports=[json.loads(p.read_text()) for p in sorted(out.glob('round-*/report.json'))]
review_path=Path(__file__).parent/'review.json'
review=json.loads(review_path.read_text()) if review_path.exists() else {'summary':'Inference pending visual review. No accuracy claim.','decisions':[]}
html='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Astra points · SAM3 boundaries</title><style>
*{box-sizing:border-box}body{margin:0;background:#eef1e7;color:#19362c;font:16px/1.5 system-ui}main{max-width:1500px;margin:auto;padding:24px}h1{font-size:32px;line-height:1.15}header p{max-width:1050px}.note{background:#fff8df;padding:16px;border-left:4px solid #b3923b}label{display:inline-block;margin:8px 20px 8px 0}select{font:inherit;padding:9px;border:1px solid #adbcaf;background:white;border-radius:6px}.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:12px}figure{margin:0;background:#fff;border-radius:9px;overflow:hidden;border:1px solid #c2cdbf}img{width:100%;display:block}figcaption{padding:12px;font-size:14px}section{margin:22px 0}a{color:#126349}#decision{background:white;padding:18px}details{margin:15px 0}pre{white-space:pre-wrap}table{border-collapse:collapse}td,th{border-bottom:1px solid #bccabc;padding:8px;text-align:left}</style>
<main><header><small>ACTUAL RUNPOD INFERENCE · RESEARCH REVIEW</small><h1>Astra points. SAM3 draws the boundaries.</h1><p>A three-case experiment with fewer manual annotations: one point per target, then corrective points chosen after inspecting model output. Pink outlines show mask boundaries; yellow dots include tissue, red dots exclude it.</p><div class="note" id="summary"></div><p>Original input: 381 × 444 pixels. Upscaling is bicubic interpolation, not new detail. Crops retain original pixels and all coordinates map back to the source. Scores below are model confidence, <b>not measured accuracy</b>. Unresolved overlaps stay unresolved.</p></header>
<section id="overview"></section><details><summary><b>Inspect every candidate, scale and correction pass</b></summary><section><label>Target <select id="target"></select></label><label>Pass <select id="round"></select></label><label>Input <select id="condition"></select></label></section><p id="context"></p><div id="decision"></div><section class="cards" id="cards"></section><details><summary>Coordinate grid for checking prompt placement</summary><img id="grid" style="max-width:612px"></details><details><summary>Exact points and run metadata</summary><pre id="metadata"></pre></details></details><section id="ledger"><h2>Three selected masks in source coordinates</h2><p>Only these three visible blades are labeled. Everything else remains unknown. No completeness claim.</p><img src="selected/source-overlay.png" style="max-width:381px"><p><a href="selected/instance-labels.png">Native instance labels (16-bit PNG)</a> · <a href="selected/labels.json">Label definitions and uncertainty</a> · <a href="selected/scale-comparison.json">Native-versus-4x mask agreement</a></p></section><p><a href="../../research/hemp-defoliation/point-loop-v1/README.md">Method and limitations</a> · <a href="../../research/hemp-defoliation/point-loop-v1/review.json">Recorded decisions</a> · <a href="../hemp-manual-segmentation-v1/index.html">Previous manual outlines</a> · <a href="https://github.com/facebookresearch/sam3">Official SAM3 implementation</a></p></main><script>
const reports=__REPORTS_DATA__,review=__REVIEW_DATA__,$=s=>document.querySelector(s);$('#summary').textContent=review.summary;
for(let t of (reports[0]?.plan.targets||[])){let sec=document.createElement('section'),title=document.createElement('h2'),note=document.createElement('p'),cards=document.createElement('div');title.textContent=t.id+' — '+t.description;cards.className='cards';let d=review.decisions.find(x=>x.target===t.id&&x.round===1&&(!x.condition||x.condition==='crop-1x'));note.textContent=d?.observation||'Pending correction review.';let n=reports.some(x=>x.plan.round===1)?1:0;for(let [file,label] of [['round-'+n+'/'+t.id+'-original.png','Original pixels; final prompt points'],['round-0/'+t.id+'-full-1x-candidate-0.png','Before: full image, one point, candidate 0'],['round-'+n+'/'+t.id+'-crop-1x-candidate-0.png','After: native crop, reviewed candidate 0']]){let f=document.createElement('figure'),i=document.createElement('img'),c=document.createElement('figcaption');i.src=file;i.alt=label;c.textContent=label;f.append(i,c);cards.append(f)}sec.append(title,note,cards);$('#overview').append(sec)}
function option(select,value,text){let o=document.createElement('option');o.value=value;o.textContent=text;select.append(o)}
if(reports.length){for(let t of reports[0].plan.targets)option($('#target'),t.id,t.id+' — '+t.description);for(let r of reports)option($('#round'),r.plan.round,r.plan.round===0?'0 · Initial point':' '+r.plan.round+' · Corrective pass');$('#round').value=reports.at(-1).plan.round;}
function conditions(){let r=reports.find(x=>x.plan.round==$('#round').value);$('#condition').replaceChildren();for(let c of r.plan.conditions)option($('#condition'),c,c);$('#condition').value=r.plan.conditions.includes('crop-1x')?'crop-1x':r.plan.conditions[0];render()}
function render(){let r=reports.find(x=>x.plan.round==$('#round').value),t=r.plan.targets.find(x=>x.id==$('#target').value),run=r.runs.find(x=>x.target===t.id&&x.condition==$('#condition').value),base='round-'+r.plan.round+'/';$('#context').textContent=t.description+' · '+t.points.length+' total prompt points · model input '+run.input_dimensions.join(' × ')+' px';$('#cards').replaceChildren();let add=(file,caption)=>{let f=document.createElement('figure'),i=document.createElement('img'),c=document.createElement('figcaption');i.src=base+file;i.alt=caption;c.textContent=caption;f.append(i,c);$('#cards').append(f)};add(t.id+'-original.png','Original pixels with current points');for(let c of run.candidates)add(run.candidate_file_prefix+'-candidate-'+c.index+'.png','Candidate '+c.index+' · '+c.mask_pixels+' source pixels · confidence '+c.model_predicted_iou_not_accuracy.toFixed(3));$('#grid').src=base+t.id+'-coordinates.png';$('#metadata').textContent=JSON.stringify({target:t,run:run,gpu:r.gpu,sam3_revision:r.sam3_revision},null,2);let decisions=review.decisions.filter(x=>x.target===t.id&&x.round==r.plan.round&&(!x.condition||x.condition==run.condition));$('#decision').textContent=decisions.map(x=>x.observation).join(' ')||'No separate visual verdict recorded for this condition. Candidate order is preserved; confidence does not establish correctness.';}
$('#round').onchange=conditions;$('#target').onchange=render;$('#condition').onchange=render;if(reports.length)conditions();
</script></html>'''
(out/'index.html').write_text(html.replace('__REPORTS_DATA__',json.dumps(reports)).replace('__REVIEW_DATA__',json.dumps(review)))
print(out/'index.html')
